1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives the owner's loyalty standing, exposed as two fields the create audit line and the owner
9	 * response both hang off: {@code membershipPoints} (the raw score) and {@code membershipLevel} (the
10	 * grade the points bucket into).
11	 *
12	 * <p>Points start at 0 and accumulate from the owner's factors: {@link #EMAIL_POINTS} for a present
13	 * email address, {@link #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
14	 * {@link #LARGE_HOUSEHOLD_POINTS} for a household of {@link #LARGE_HOUSEHOLD_SIZE} or more, and
15	 * {@link #TENURE_POINTS} for more than {@link #TENURE_FISCAL_YEARS_FOR_POINTS} elapsed fiscal
16	 * year(s) of tenure since {@code registrationDate}, where fiscal years start on 1 July (see
17	 * {@link FiscalYears}). A freshly created owner registers as of today and so has zero tenure.
18	 *
19	 * <p>Points map to a level of 1 (0-1 points), 2 (2-3), 3 (4-5) or 4 (6 or more).
20	 */
21	public final class Memberships {
22	
23	    /** Points awarded for a present (non-blank) email address. */
24	    private static final int EMAIL_POINTS = 2;
25	
26	    /** Points awarded when the owner has no namesakes ({@code namesakeCount == 0}). */
27	    private static final int NO_NAMESAKE_POINTS = 1;
28	
29	    /** Points awarded for belonging to a household of {@link #LARGE_HOUSEHOLD_SIZE} or more. */
30	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
31	
32	    /** Household size (members inclusive) at which {@link #LARGE_HOUSEHOLD_POINTS} is awarded. */
33	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
34	
35	    /** Points awarded for more than {@link #TENURE_FISCAL_YEARS_FOR_POINTS} elapsed fiscal years of tenure. */
36	    private static final int TENURE_POINTS = 3;
37	
38	    /** Elapsed fiscal years of tenure that must be exceeded to earn {@link #TENURE_POINTS}. */
39	    private static final int TENURE_FISCAL_YEARS_FOR_POINTS = 1;
40	
41	    private Memberships() {
42	    }
43	
44	    /**
45	     * The owner's {@code membershipPoints}: the raw loyalty score built from a present email, no
46	     * namesakes, a large household and tenure. {@code householdSize} is the number of owners sharing
47	     * this owner's household (members inclusive).
48	     */
49	    public static int membershipPoints(Owner owner, long householdSize) {
50	        int points = 0;
51	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
52	        if (hasEmail) {
53	            points += EMAIL_POINTS;
54	        }
55	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
56	        if (noNamesakes) {
57	            points += NO_NAMESAKE_POINTS;
58	        }
59	        if (householdSize >= LARGE_HOUSEHOLD_SIZE) {
60	            points += LARGE_HOUSEHOLD_POINTS;
61	        }
62	        if (hasTenureForPoints(owner)) {
63	            points += TENURE_POINTS;
64	        }
65	        return points;
66	    }
67	
68	    /**
69	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
70	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
71	     */
72	    public static int membershipLevel(int points) {
73	        if (points <= 1) {
74	            return 1;
75	        }
76	        if (points <= 3) {
77	            return 2;
78	        }
79	        if (points <= 5) {
80	            return 3;
81	        }
82	        return 4;
83	    }
84	
85	    private static boolean hasTenureForPoints(Owner owner) {
86	        LocalDate registrationDate = owner.getRegistrationDate();
87	        if (registrationDate == null) {
88	            return false;
89	        }
90	        int tenureFiscalYears = FiscalYears.elapsed(registrationDate, LocalDate.now());
91	        return tenureFiscalYears > TENURE_FISCAL_YEARS_FOR_POINTS;
92	    }
93	}
