1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
36	    @Mapping(target = "initials",
37	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
38	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
39	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
40	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
41	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
42	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
