202	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
203	     * legacy seed owners).
204	     */
205	    protected Integer checkDigit(Owner owner) {
206	        String customerCode = owner.getCustomerCode();
207	        if (customerCode == null) {
208	            return null;
209	        }
210	        int sum = 0;
211	        boolean dbl = true;
212	        for (int i = customerCode.length() - 1; i >= 0; i--) {
213	            char c = customerCode.charAt(i);
214	            if (c < '0' || c > '9') {
215	                continue;
216	            }
217	            int d = c - '0';
218	            if (dbl) {
219	                d *= 2;
220	                if (d > 9) {
221	                    d -= 9;
222	                }
223	            }
224	            sum += d;
225	            dbl = !dbl;
226	        }
227	        return (10 - (sum % 10)) % 10;
228	    }
