7	/**
8	 * Flags a soft-match duplicate, keyed on the computed {@link Households#id(Owner) householdId}. A
9	 * new owner that shares an existing owner's household (same last name and postcode) but carries a
10	 * different telephone is created with {@code possibleDuplicate} set true and {@code possibleDuplicateOf}
11	 * set to the matching owner's id.
12	 *
13	 * <p>A declared household member (request {@code sharesHousehold} true) is NOT a suspected duplicate:
14	 * it deliberately joins an existing household, so it is created with {@code possibleDuplicate} false.
15	 * Any other owner reaching this step is not a household duplicate ({@link EnsureUniqueIdentity} has
16	 * already rejected those), so it too is left unflagged.
17	 *
18	 * <p>Runs before {@link SaveOwner} so the new owner has not been persisted yet and is not compared
19	 * against itself. The earliest matching owner (lowest id) is chosen for stability.
20	 */
21	public class AssignPossibleDuplicate {
22	
23	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
24	        if (Boolean.TRUE.equals(sharesHousehold)) {
25	            // Declared household member: a deliberate join, not a suspected duplicate.
26	            owner.setPossibleDuplicate(Boolean.FALSE);
27	            return;
28	        }
29	        String householdId = owner.getHouseholdId();
30	        String telephone = owner.getTelephone();
31	        Owner match = ownerRepository.findAll().stream()
32	                .filter(existing -> !existing.getId().equals(owner.getId()))
33	                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted())) // ignore soft-deleted owners
34	                .filter(existing -> householdId.equals(Households.id(existing))
35	                        && !equalsIgnoreCase(existing.getTelephone(), telephone))
36	                .min(java.util.Comparator.comparing(Owner::getId))
37	                .orElse(null);
38	        if (match != null) {
39	            owner.setPossibleDuplicate(Boolean.TRUE);
40	            owner.setPossibleDuplicateOf(match.getId());
41	        }
42	        else {
43	            owner.setPossibleDuplicate(Boolean.FALSE);
44	        }
45	    }
46	
47	    private static boolean equalsIgnoreCase(String a, String b) {
48	        return a == null ? b == null : a.equalsIgnoreCase(b);
49	    }
50	}
